compare.check:
(args, got, expected) => {
      const { ops, args: a } = args;
      if (!Array.isArray(got) || got.length !== ops.length) return false;
      const s = new Set();
      let seen = new Set(), streak = 0;
      const endStreak = () => {
        if (streak >= 60 && s.size <= 5 && seen.size < s.size) return false;
        seen = new Set(); streak = 0;
        return true;
      };
      for (let i = 0; i < ops.length; i++) {
        const op = ops[i], v = a[i][0];
        if (op === "RandomizedSet") { if (got[i] !== null) return false; }
        else if (op === "insert") {
          const ok = !s.has(v);
          if (got[i] !== ok) return false;
          if (ok) { if (!endStreak()) return false; s.add(v); }
        } else if (op === "remove") {
          const ok = s.has(v);
          if (got[i] !== ok) return false;
          if (ok) { if (!endStreak()) return false; s.delete(v); }
        } else if (op === "getRandom") {
          if (!s.has(got[i])) return false;
          seen.add(got[i]); streak++;
        } else return false;
      }
      return endStreak();
    }
